    },
    "coverAlt": {
      "type": "string",
      "required": false,
      "description": "Cover image alt text."
    },
    "href": {
      "type": "string",
      "required": false,
      "description": "Target URL for the read action."
    },
    "readLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the read action."
    },
    "className": {
      "type": "string",
      "required": false,
