.cu-article-card {
  display: block;
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  overflow: hidden;
}

.cu-article-card__cover {
  display: block;
  inline-size: 100%;
  block-size: auto;
}

.cu-article-card__body {
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-article-card__title {
  margin: 0;
  font-size: 1.125em;
}

.cu-article-card__excerpt {
  margin: var(--cu-space-1) 0 0;
  color: color-mix(in srgb, var(--cu-color-fg-default) 80%, transparent);
}

.cu-article-card__meta {
  display: flex;
  gap: var(--cu-space-2);
  margin-block-start: var(--cu-space-2);
  font-size: 0.875em;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

.cu-article-card__read {
  display: inline-block;
  margin-block-start: var(--cu-space-2);
  color: var(--cu-color-palette-brand);
}
